    return has_content;
}

// Scratch state for one malformed literal; it never enters incremental serialization.
typedef enum { LEX_TEXT, LEX_HOLE, LEX_GROUP, LEX_FORMAT } LexMode;
typedef enum { LEX_NORMAL, LEX_VERBATIM, LEX_RAW_SINGLE, LEX_RAW_MULTI } LexKind;
typedef struct {
    LexMode mode;
    LexKind kind;
    uint64_t dollars, quotes;
    size_t owner;
    int32_t ending;
    bool interpolated, error;
} LexFrame;
typedef struct { LexFrame *items; size_t size, capacity; } LexStack;

static void lex_failure(void) { _Exit(2); }

static uint64_t lex_run(TSLexer *lexer, int32_t c) {
    uint64_t count = 0;
    while (!lexer->eof(lexer) && lexer->lookahead == c) {
        if (count == UINT64_MAX) lex_failure();
        count++;
        advance(lexer);
    }
    return count;
}

static void lex_push(LexStack *stack, LexFrame frame) {
    if (stack->size == stack->capacity) {
        if (stack->capacity > SIZE_MAX / 2) lex_failure();
        size_t capacity = stack->capacity ? stack->capacity * 2 : 16;
        if (capacity > SIZE_MAX / sizeof(LexFrame)) lex_failure();
        LexFrame *items = ts_realloc(stack->items, capacity * sizeof(LexFrame));
        if (!items) lex_failure();
        stack->items = items;
        stack->capacity = capacity;
    }
    stack->items[stack->size++] = frame;
}

static void lex_newline(TSLexer *lexer) {
    int32_t first = lexer->lookahead;
    advance(lexer);
    if (first == '\r' && lexer->lookahead == '\n') advance(lexer);
}

static LexFrame lex_literal(TSLexer *lexer, uint64_t dollars, uint64_t quotes,
                            uint64_t ats, bool character, size_t owner) {
    LexFrame frame = {.mode = LEX_TEXT, .dollars = dollars, .quotes = quotes,
                      .owner = owner, .ending = character ? '\'' : '"',
                      .interpolated = dollars != 0};
    if (character) {
        frame.kind = LEX_NORMAL;
    } else if (dollars > 1 || (dollars && ats > 1) || (!ats && quotes >= 3)) {
        frame.error = quotes < 3 || ats != 0;
        while (is_pp_space(lexer->lookahead)) advance(lexer);
        frame.kind = is_pp_new_line(lexer->lookahead) ? LEX_RAW_MULTI : LEX_RAW_SINGLE;
        if (frame.kind == LEX_RAW_MULTI) lex_newline(lexer);
    } else {
        frame.kind = ats ? LEX_VERBATIM : LEX_NORMAL;
        frame.error = ats > 1;
    }
    return frame;
}

static void lex_escape(TSLexer *lexer, bool *error) {
    advance(lexer);
    if (lexer->eof(lexer)) return;
    int32_t c = lexer->lookahead;
    advance(lexer);
    uint64_t value = (uint32_t)c;
    unsigned digits = c == 'x' ? 4 : c == 'u' ? 4 : c == 'U' ? 8 : 0;
    if (digits) {
        value = 0;
        for (unsigned i = 0; i < digits; i++) {
            int32_t h = lexer->lookahead;
            unsigned n;
            if (h >= '0' && h <= '9') n = (unsigned)(h - '0');
            else if (h >= 'a' && h <= 'f') n = (unsigned)(h - 'a') + 10;
            else if (h >= 'A' && h <= 'F') n = (unsigned)(h - 'A') + 10;
            else break;
            value = value * 16 + n;
            advance(lexer);
        }
    }
    if (value == '{' || value == '}') *error = true;
}

static void lex_comment(TSLexer *lexer, int32_t delimiter) {
    while (!lexer->eof(lexer)) {
        bool star = lexer->lookahead == '*';
        advance(lexer);
        if (star && lexer->lookahead == delimiter) { advance(lexer); return; }
    }
}

static bool lex_pp_string(TSLexer *lexer, bool allow_raw) {
    uint64_t quotes = lex_run(lexer, '"');
    if (quotes >= 3) {
        if (!allow_raw) return false;
        while (is_pp_space(lexer->lookahead)) advance(lexer);
        bool multiline = is_pp_new_line(lexer->lookahead);
        if (multiline) lex_newline(lexer);
        while (!lexer->eof(lexer)) {
            if (!multiline && is_pp_new_line(lexer->lookahead)) break;
            if (lexer->lookahead == '"') { if (lex_run(lexer, '"') >= quotes) break; }
            else advance(lexer);
        }
        return false;
    }
    if (quotes == 2) return true;
    while (!lexer->eof(lexer) && !is_pp_new_line(lexer->lookahead)) {
        int32_t c = lexer->lookahead;
        advance(lexer);
        if (c == '"') return true;
    }
    return false;
}

static void lex_pp_tail(TSLexer *lexer) {
    while (!lexer->eof(lexer) && !is_pp_new_line(lexer->lookahead)) {
        if (lexer->lookahead == '"') (void)lex_pp_string(lexer, true);
        else if (lexer->lookahead == '/') {
            advance(lexer);
            if (lexer->lookahead == '/')
                while (!lexer->eof(lexer) && !is_pp_new_line(lexer->lookahead)) advance(lexer);
        } else advance(lexer);
    }
}

// A prefix is consumed only by the selected recovery handler, never by a fall-through.
static void lex_nested(TSLexer *lexer, LexStack *stack) {
    int32_t first = lexer->lookahead;
    if (first == '\'') {
        advance(lexer);
        LexFrame frame = lex_literal(lexer, 0, 1, 0, true, stack->size);
        lex_push(stack, frame);
        return;
    }
    uint64_t ats = lex_run(lexer, '@');
    if (ats == 1 && lexer->lookahead == '*') {
        advance(lexer);
        lex_comment(lexer, '@');
        return;
    }
    uint64_t dollars = lex_run(lexer, '$');
    if (dollars) {
        uint64_t trailing = lex_run(lexer, '@');
        if (trailing > UINT64_MAX - ats) lex_failure();
        ats += trailing;
    }
    if (lexer->lookahead != '"') return;
    bool verbatim = ats && dollars <= 1;
    uint64_t quotes;
    if (verbatim) { advance(lexer); quotes = 1; }
    else quotes = lex_run(lexer, '"');
    if (!ats && dollars <= 1 && quotes == 2) return;
    LexFrame frame = lex_literal(lexer, dollars, quotes, ats, false, stack->size);
    lex_push(stack, frame);
}

static void lex_close_hole(TSLexer *lexer, LexStack *stack) {
    LexFrame frame = stack->items[stack->size - 1];
    LexFrame *owner = &stack->items[frame.owner];
    uint64_t need = owner->dollars;
    uint64_t count = 0;
    while (count < need && lexer->lookahead == '}') { advance(lexer); count++; }
    if (count < need) owner->error = true;
    stack->size--;
}

static void lex_walk(TSLexer *lexer, LexFrame root) {
    LexStack stack = {0};
    lex_push(&stack, root);
    while (stack.size && !lexer->eof(lexer)) {
        LexFrame *frame = &stack.items[stack.size - 1];
        LexFrame *owner = &stack.items[frame->owner];
        int32_t c = lexer->lookahead;
        if (frame->mode == LEX_TEXT) {
            bool raw = frame->kind == LEX_RAW_SINGLE || frame->kind == LEX_RAW_MULTI;
            if ((frame->kind == LEX_NORMAL || frame->kind == LEX_RAW_SINGLE) && is_pp_new_line(c)) {
                stack.size--;
                continue;
            }
            if (c == frame->ending) {
                if (raw) {
                    if (lex_run(lexer, '"') >= frame->quotes) stack.size--;
                } else {
                    advance(lexer);
                    if (frame->kind == LEX_VERBATIM && !frame->error && lexer->lookahead == '"') advance(lexer);
                    else stack.size--;
                }
                continue;
            }
            if (frame->kind == LEX_NORMAL && c == '\\') {
                bool error = false;
                lex_escape(lexer, &error);
                if (frame->interpolated) frame->error |= error;
                continue;
            }
            if (frame->interpolated && (c == '{' || c == '}')) {
                uint64_t count;
                if (raw) count = lex_run(lexer, c);
                else {
                    advance(lexer);
                    if (lexer->lookahead == c) { advance(lexer); continue; }
                    count = 1;
                }
                if (c == '}') { if (count >= frame->dollars) frame->error = true; }
                else if (count >= frame->dollars) {
                    if (raw && count - frame->dollars >= frame->dollars) frame->error = true;
                    LexFrame hole = {.mode = LEX_HOLE, .owner = frame->owner, .ending = '}'};
                    lex_push(&stack, hole);
                }
                continue;
            }
            advance(lexer);
            continue;
        }
        if (frame->mode == LEX_FORMAT) {
            if (c == '}') { lex_close_hole(lexer, &stack); continue; }
            if (c == '"') {
                if (owner->kind == LEX_VERBATIM) {
                    advance(lexer);
                    if (lexer->lookahead == '"') { advance(lexer); continue; }
                    owner->error = true;
                    stack.size = frame->owner;
                } else {
                    owner->error = true;
                    stack.size = frame->owner + 1;
                }
                continue;
            }
            if (c == '\\' && owner->kind == LEX_NORMAL) { lex_escape(lexer, &owner->error); continue; }
            if (c == '{') owner->error = true;
            advance(lexer);
            continue;
        }
        if (c == '"' && owner->error) { stack.size = frame->owner + 1; continue; }
        if (c == frame->ending) {
            if (frame->mode == LEX_HOLE) lex_close_hole(lexer, &stack);
            else { advance(lexer); stack.size--; }
            continue;
        }
        if (c == ')' || c == ']' || c == '}') { owner->error = true; advance(lexer); continue; }
        if (c == ':' && frame->mode == LEX_HOLE) { advance(lexer); frame->mode = LEX_FORMAT; continue; }
        if (c == '#') { owner->error = true; advance(lexer); continue; }
        if (c == '(' || c == '[' || c == '{') {
            LexFrame group = {.mode = LEX_GROUP, .owner = frame->owner, .ending = c == '(' ? ')' : c == '[' ? ']' : '}'};
            advance(lexer);
            lex_push(&stack, group);
            continue;
        }
        if (c == '/') {
            advance(lexer);
            if (lexer->lookahead == '/') {
                while (!lexer->eof(lexer) && !is_pp_new_line(lexer->lookahead)) advance(lexer);
            } else if (lexer->lookahead == '*') { advance(lexer); lex_comment(lexer, '/'); }
            continue;
        }
        if (c == '"' || c == '\'' || c == '$' || c == '@') { lex_nested(lexer, &stack); continue; }
        advance(lexer);
    }
    ts_free(stack.items);
}

static bool lex_recovery_start(TSLexer *lexer) {
    uint64_t ats = lex_run(lexer, '@');
    if (ats == 1 && lexer->lookahead == '*') {
        advance(lexer);
        lex_comment(lexer, '@');
        lexer->mark_end(lexer);
        lexer->result_symbol = LEXICAL_ERROR;
        return true;
    }
    uint64_t dollars = lex_run(lexer, '$');
    uint64_t trailing = dollars ? lex_run(lexer, '@') : 0;
    if (trailing > UINT64_MAX - ats) lex_failure();
    ats += trailing;
    if (dollars && ats && lexer->lookahead == '$') {
        LexStack next = {0};
        while (lexer->lookahead == '$') {
            lex_nested(lexer, &next);
            if (next.size) { lex_walk(lexer, next.items[0]); break; }
        }
        ts_free(next.items);
        lexer->mark_end(lexer);
        lexer->result_symbol = LEXICAL_ERROR;
        return true;
    }
    if (!(dollars > 1 || (dollars && ats > 1)) || lexer->lookahead != '"') return false;
    uint64_t quotes = lex_run(lexer, '"');
    if (!quotes || (quotes >= 3 && !ats)) return false;
    LexFrame root = lex_literal(lexer, dollars, quotes, ats, false, 0);
    root.error = true;
    lex_walk(lexer, root);
    lexer->mark_end(lexer);
    lexer->result_symbol = LEXICAL_ERROR;
    return true;
}

